    Test("cancel after reset high attempt forbids all tail frames",[]{MockCanBus b;b.SetObject(0x6041,0,0xc0,2);b.SetObject(0x603f,0,0x2312,2);Controller c(b,Config());auto p=c.Review(Action::ResetAlarm);std::atomic_bool cancel{false};b.on_send=[&](const nimotion::Frame& f,MockCanBus&){if(Index(f)==0x6040&&f.data[0]==0x2b&&nimotion::decode(f.data.data()+4,2)==0x80)cancel=true;};auto r=c.Execute(p.token,cancel);Check(!r.success&&r.isolated,"reset cancelled without lock");Check(Controls(b)==std::vector<std::uint16_t>({0,0x80}),"reset appended low");NoMoreFrames(c,b);});
