    Test("other protection lock cannot be replaced by later Warning2312",[]{MockCanBus b;Controller c(b,Config());auto p=c.Review(Action::Forward);b.SetObject(0x605d,0,2,2);std::atomic_bool cancel{false};auto r=c.Execute(p.token,cancel);Check(!r.success&&!r.isolated,"changed parameter policy lock fixture");b.SetObject(0x605d,0,1,2);b.SetObject(0x6041,0,0xc0,2);b.SetObject(0x603f,0,0x2312,2);c.Poll();auto n=b.downloads();Throws([&]{c.Review(Action::ResetAlarm);},"保护锁");Check(b.downloads()==n,"unrelated lock cleared");});
    Test("known quickstop abort still permits separate disable",[]{MockCanBus b;Controller c(b,Config());Check(Move(c,Action::Hold).success,"hold fixture");bool injected=false;b.on_send=[&](const nimotion::Frame& f,MockCanBus& bus){if(Index(f)==0x6040&&f.data[0]==0x2b&&nimotion::decode(f.data.data()+4,2)==2){bus.abort_index=0x6040;injected=true;}else if(injected)bus.abort_index.reset();};auto r=c.SafetyStop(true);Check(!r.success&&r.disabled_confirmed&&!r.isolated,"known abort no disable");auto cw=Controls(b);Check(cw[cw.size()-2]==2&&cw.back()==0,"disable not attempted after known abort");Check(r.message.find("abort")!=std::string::npos,"original error lost");});
    Test("partial alarm observation survives next transaction timeout",[]{MockCanBus b;Controller c(b,Config());c.Poll();b.SetObject(0x6041,0,0xc0,2);b.SetObject(0x603f,0,0x2312,2);b.on_send=[](const nimotion::Frame& f,MockCanBus& bus){if(Index(f)==0x1001)bus.SetTimeoutAfter(bus.Frames().size()-1);};Throws([&]{c.Poll();},"SDO");auto v=c.LastSnapshot();Check(!v.valid&&v.statusword_known&&v.error_code_known&&!v.position_known,"partial known flags");Check(v.error_code==0x2312&&v.alarm.find("电机堵转")!=std::string::npos,"partial alarm overwritten");NoMoreFrames(c,b);});
    Test("first failure snapshot remains before cleanup writes",[]{MockCanBus b;Controller c(b,Config());b.on_send=[](const nimotion::Frame& f,MockCanBus& bus){if(Index(f)==0x6041&&bus.GetObject(0x6040).value==0x106){bus.SetObject(0x6041,0,0xa1,2);bus.SetObject(0x603f,0,0x2312,2);}};auto r=Move(c);Check(!r.success&&r.snapshot.error_code==0x2312&&r.snapshot.controlword==0x106,"cleanup overwrote first snapshot");Check(r.snapshot.phase.find("迁移")!=std::string::npos,"failure phase lost");});
    Test("fresh demand must match preloaded target",[]{MockCanBus b;Controller c(b,Config());b.on_send=[](const nimotion::Frame& f,MockCanBus& bus){if(Index(f)==0x6062&&bus.GetObject(0x6040).value==0x137)bus.SetObject(0x6062,0,12345,4);};auto r=Move(c);Check(!r.success,"stale demand accepted");auto cw=Controls(b);Check(std::find(cw.begin(),cw.end(),0x12f)==cw.end(),"stale demand enabled");});
    Test("diagnostics preserve attempt ACK and reset samples",[]{MockCanBus b;Controller c(b,Config());std::vector<std::string> logs;c.SetDiagnostics([&](const std::string& text){logs.push_back(text);});auto r=Move(c,Action::Hold);Check(r.success,r.message);Check(std::count_if(logs.begin(),logs.end(),[](const std::string& s){return s.find("下载尝试")!=std::string::npos;})==6,"attempt logs missing");Check(std::count_if(logs.begin(),logs.end(),[](const std::string& s){return s.find("下载SDO ACK")!=std::string::npos;})==6,"ACK logs missing");});
